13	// 数据目录布局：
14	//
15	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
16	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
17	//
18	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
19	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
20	
21	const stateVersion = 1
