103	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
104	func (s *state) validate() error {
105		if s.Version != stateVersion {
106			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
107		}
108		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
109			return errors.New("缺少必要的数据节")
110		}
111		for id, c := range s.Customers {
112			if c == nil {
113				return fmt.Errorf("客户 %q 的数据为空", id)
114			}
115			if c.ID != id {
116				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
117			}
118			if c.ID == "" || c.Name == "" {
119				return fmt.Errorf("客户 %q 的标识或名称为空", id)
120			}
121			if c.Price < 0 {
122				return fmt.Errorf("客户 %q 单价为负", id)
123			}
124		}
125		for id, u := range s.Usage {
126			if u == nil {
127				return fmt.Errorf("用量 %q 的数据为空", id)
128			}
129			if u.ID != id {
130				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
131			}
132			if u.ID == "" {
133				return errors.New("存在空的用量标识")
134			}
135			if _, ok := s.Customers[u.CustomerID]; !ok {
136				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
137			}
138			if u.Quantity <= 0 {
139				return fmt.Errorf("用量 %q 的数量非正", u.ID)
140			}
141			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
142				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
143			}
144		}
145		for key, b := range s.Bills {
146			if b == nil {
147				return fmt.Errorf("账单 %q 的数据为空", key)
148			}
149			if billKey(b.CustomerID, b.Month) != key {
150				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
151			}
152			if _, ok := s.Customers[b.CustomerID]; !ok {
153				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
154			}
155			if !validMonth(b.Month) {
156				return fmt.Errorf("账单 %q 的月份无效", key)
157			}
158			if len(b.Lines) == 0 {
159				return fmt.Errorf("账单 %q 没有明细", key)
160			}
161			var qty, fee int64
162			for _, ln := range b.Lines {
163				u, ok := s.Usage[ln.UsageID]
164				if !ok {
165					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
166				}
167				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
168					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
169				}
170				if !inMonth(u.Time, b.Month) {
171					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
172				}
173				var err error
174				qty, err = add64(qty, ln.Quantity)
175				if err != nil {
176					return fmt.Errorf("账单 %q 汇总数量溢出", key)
177				}
178				fee, err = add64(fee, ln.LineFee)
179				if err != nil {
180					return fmt.Errorf("账单 %q 汇总金额溢出", key)
181				}
182			}
183			if qty != b.TotalQty {
184				return fmt.Errorf("账单 %q 总数量与明细不符", key)
185			}
186			if fee != b.TotalFee {
187				return fmt.Errorf("账单 %q 总金额与明细不符", key)
188			}
189			c := s.Customers[b.CustomerID]
190			for _, ln := range b.Lines {
191				lf, err := mul64(ln.Quantity, c.Price)
192				if err != nil {
193					return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
194				}
195				if lf != ln.LineFee {
196					return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
197				}
198			}
199			if b.UnitPrice != c.Price {
200				return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
201			}
202			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
203			// 而已入账记录理应全部在明细中）。
204			for _, u := range s.Usage {
205				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
206					found := false
207					for _, ln := range b.Lines {
208						if ln.UsageID == u.ID {
209							found = true
210							break
211						}
212					}
213					if !found {
214						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
215					}
216				}
217			}
218		}
219		return nil
220	}
