228	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
229	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
230		cr := csv.NewReader(r)
231		cr.FieldsPerRecord = 4
232		cr.TrimLeadingSpace = true
233	
